// 할 일 규칙: 화면과 분리된 순수 함수. 브라우저에서는 window.Todo, Node에서는 require로 쓴다.
(function (root) {
  function addTodo(list, text) {
    const title = String(text ?? '').trim();
    if (!title) return list;
    return [...list, { id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6), title, done: false }];
  }
  function toggleTodo(list, id) {
    return list.map(item => (item.id === id ? { ...item, done: !item.done } : item));
  }
  function removeTodo(list, id) {
    return list.filter(item => item.id !== id);
  }
  const api = { addTodo, toggleTodo, removeTodo };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.Todo = api;
})(this);

