const test = require('node:test');
const assert = require('node:assert/strict');
const { addTodo, toggleTodo, removeTodo } = require('./todo.js');

test('할 일을 추가한다', () => {
  const list = addTodo([], '우유 사기');
  assert.equal(list.length, 1);
  assert.equal(list[0].title, '우유 사기');
  assert.equal(list[0].done, false);
});

test('빈 문자열은 추가하지 않는다', () => {
  assert.deepEqual(addTodo([], '   '), []);
});

test('완료를 전환하고 삭제한다', () => {
  const [item] = addTodo([], '청소');
  const toggled = toggleTodo([item], item.id);
  assert.equal(toggled[0].done, true);
  assert.deepEqual(removeTodo(toggled, item.id), []);
});

