// 화면: window.Todo 규칙으로 목록을 그리고 localStorage에 저장한다.
(function () {
  const KEY = 'todo-app-items';
  let items = [];
  try { items = JSON.parse(localStorage.getItem(KEY) || '[]'); } catch { items = []; }
  const list = document.getElementById('list');
  const empty = document.getElementById('empty');
  const input = document.getElementById('new-todo');
  function save() { try { localStorage.setItem(KEY, JSON.stringify(items)); } catch {} }
  function render() {
    list.innerHTML = '';
    for (const item of items) {
      const li = document.createElement('li');
      if (item.done) li.className = 'done';
      const title = document.createElement('span');
      title.textContent = item.title;
      title.title = '눌러서 완료 표시';
      title.onclick = () => { items = Todo.toggleTodo(items, item.id); save(); render(); };
      const remove = document.createElement('button');
      remove.textContent = '삭제';
      remove.onclick = () => { items = Todo.removeTodo(items, item.id); save(); render(); };
      li.append(title, remove);
      list.append(li);
    }
    empty.hidden = items.length > 0;
  }
  document.getElementById('add-form').addEventListener('submit', event => {
    event.preventDefault();
    items = Todo.addTodo(items, input.value);
    input.value = '';
    save();
    render();
  });
  render();
})();
